class Base {
public:
  virtual void doWork();
  virtual void process(int val) const;
};

class Derived : public Base {
public:
  // Correctly overrides Base::doWork
  void doWork() override;

  // ERROR: signature mismatch (missing const)
  // The compiler would catch this because of 'override'.
  // Without 'override', this would just be a new function.
  // void process(int val) override; 
};

class DerivedCorrect : public Base {
public:
  void doWork() override;
  void process(int val) const override; // Correct override
};
